32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    /** Minimal syntactic check for an email address: a non-empty local part, a single
60	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
61	    private static final Pattern EMAIL_PATTERN =
62	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().replaceAll("\\D", "");
113	        if (telephone.length() != 10) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        owner.setTelephone(telephone);
117	        String email = owner.getEmail();
118	        if (email != null) {
119	            email = email.trim();
120	            if (!EMAIL_PATTERN.matcher(email).matches()) {
121	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	            }
123	            owner.setEmail(email.toLowerCase(Locale.ROOT));
124	        }
125	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
126	            .map(Owner::getTelephone)
127	            .filter(Objects::nonNull)
128	            .map(existing -> existing.replaceAll("\\D", ""))
129	            .anyMatch(telephone::equals);
130	        if (telephoneInUse) {
131	            return new ResponseEntity<>(HttpStatus.CONFLICT);
132	        }
133	        this.clinicService.saveOwner(owner);
134	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
135	        headers.setLocation(UriComponentsBuilder.newInstance()
136	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
137	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
143	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
144	        if (currentOwner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        currentOwner.setAddress(ownerFieldsDto.getAddress());
148	        currentOwner.setCity(ownerFieldsDto.getCity());
149	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
150	        currentOwner.setLastName(ownerFieldsDto.getLastName());
151	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
152	        this.clinicService.saveOwner(currentOwner);
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Transactional
158	    @Override
159	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        this.clinicService.deleteOwner(owner);
165	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        HttpHeaders headers = new HttpHeaders();
176	        Pet pet = petMapper.toPet(petFieldsDto);
177	        owner.setId(ownerId);
178	        pet.setOwner(owner);
179	        pet.getType().setName(null);
180	        this.clinicService.savePet(pet);
181	        PetDto petDto = petMapper.toPetDto(pet);
182	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
183	            .buildAndExpand(pet.getId()).toUri());
184	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner != null) {
192	            Pet currentPet = this.clinicService.findPetById(petId);
193	            if (currentPet != null) {
194	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
195	                currentPet.setName(petFieldsDto.getName());
196	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
197	                this.clinicService.savePet(currentPet);
198	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
199	            }
200	        }
201	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
207	        HttpHeaders headers = new HttpHeaders();
208	        Visit visit = visitMapper.toVisit(visitFieldsDto);
209	        Pet pet = new Pet();
210	        pet.setId(petId);
211	        visit.setPet(pet);
212	        this.clinicService.saveVisit(visit);
213	        VisitDto visitDto = visitMapper.toVisitDto(visit);
214	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
215	            .buildAndExpand(visit.getId()).toUri());
216	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
217	    }
218	
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner != null) {
225	            Pet pet = owner.getPet(petId);
226	            if (pet != null) {
227	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
228	            }
229	        }
230	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	    }
232	}
